package os.aios.core.workspace;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.MessageDigest;import java.util.*;import org.json.*;

/** File assets are the sole editable skill source of truth. */
final class SkillFileStore{
 private final File root,staging;SkillFileStore(WorkspaceStore store){root=store.skillRoot();staging=new File(root,".staging");root.mkdirs();staging.mkdirs();recover();}
 List<JSONObject> list()throws Exception{return list(false);}
 private List<JSONObject> list(boolean deleted)throws Exception{List<JSONObject> out=new ArrayList<>();File[] dirs=root.listFiles(File::isDirectory);if(dirs==null)return out;for(File d:dirs){if(d.getName().startsWith("."))continue;JSONObject m=read(d.getName(),deleted);if(m!=null)out.add(m);}return out;}
 JSONObject get(String id)throws Exception{JSONObject m=read(id,false);if(m==null||m.optBoolean("deleted"))throw new IllegalArgumentException("Skill missing or deleted");return m.put("content_md",body(id,m.getLong("revision"))).put("assets",readAssets(id,m.getLong("revision")));}
 JSONObject findCapability(String capability,String pkg)throws Exception{if(capability.isEmpty())return null;for(JSONObject m:list(true))if(capability.equals(m.optString("capability_id"))&&pkg.equals(m.optString("package")))return m;return null;}
 JSONObject findDedupe(String dedupe)throws Exception{for(JSONObject m:list(true))if(m.getString("dedupe").equals(dedupe))return m;return null;}
 JSONObject publish(String publishId,JSONObject metadata,String body,JSONObject assets,long expectedRevision)throws Exception{
  String id=metadata.getString("id");JSONObject current=read(id,true);if(current!=null&&current.optBoolean("deleted"))throw new IllegalStateException("Skill was deleted");long old=current==null?0:current.getLong("revision");if(old!=expectedRevision)throw new IllegalStateException("内容已更新，请重新打开后再编辑");
  validateId(id);validateMetadata(metadata,assets);
  long revision=old+1;metadata.put("publication_id",publishId).put("expected_revision",old).put("revision",revision).put("updated_at",System.currentTimeMillis()).put("deleted",false);if(old==0)metadata.put("created_at",metadata.optLong("created_at",System.currentTimeMillis()));else metadata.put("created_at",current.getLong("created_at"));
  File prep=new File(staging,publishId);delete(prep);if(!prep.mkdirs())throw new IOException("Cannot create skill staging directory");writeSync(new File(prep,"SKILL.md"),skillMarkdown(metadata,body));writeAssets(prep,assets);metadata.put("asset_paths",new JSONArray(sortedKeys(assets)));writeSync(new File(prep,"manifest.json"),metadata.toString());
  File versions=new File(new File(root,id),"versions"),target=new File(versions,Long.toString(revision));versions.mkdirs();move(prep,target);writePointer(new File(root,id),revision);return get(id);
 }
 JSONObject importLegacyTombstone(JSONObject metadata)throws Exception{String id=metadata.getString("id");validateId(id);JSONObject existing=read(id,true);if(existing!=null){if(!existing.optBoolean("deleted"))throw new IOException("Legacy tombstone conflicts with live file");return existing;}JSONObject tomb=new JSONObject(metadata.toString());tomb.remove("content_md");tomb.put("deleted",true).put("enabled",false).put("user_edited",true);writeSync(new File(new File(root,id),"TOMBSTONE"),tomb.toString());return read(id,true);}
 JSONObject importLegacy(JSONObject metadata,String body)throws Exception{
  String id=metadata.getString("id");if(read(id,true)!=null)return read(id,true);long revision=Math.max(1,metadata.getLong("revision"));File prep=new File(staging,"migration-"+id);delete(prep);if(!prep.mkdirs())throw new IOException("Cannot create migration staging directory");writeSync(new File(prep,"SKILL.md"),skillMarkdown(metadata,body));writeSync(new File(prep,"manifest.json"),metadata.toString());File versions=new File(new File(root,id),"versions"),target=new File(versions,Long.toString(revision));versions.mkdirs();if(target.exists()){if(!readText(new File(target,"manifest.json")).equals(metadata.toString())||!readText(new File(target,"SKILL.md")).equals(skillMarkdown(metadata,body)))throw new IOException("Incomplete or conflicting legacy publication");delete(prep);}else move(prep,target);writePointer(new File(root,id),revision);return get(id);
 }
 JSONObject rollback(String id,long revision,long expected)throws Exception{JSONObject current=get(id);if(current.getLong("revision")!=expected)throw new IllegalStateException("内容已更新，请重新打开后再编辑");File source=new File(new File(new File(root,id),"versions"),Long.toString(revision));if(!new File(source,"manifest.json").isFile())throw new IllegalArgumentException("Skill version missing");JSONObject prior=new JSONObject(readText(new File(source,"manifest.json")));prior.put("id",id).put("user_edited",true).put("enabled",current.optBoolean("enabled",true));return publish("rollback-"+id+"-"+UUID.randomUUID(),prior,body(id,revision),readAssets(id,revision),expected);}
 JSONObject delete(String id,long expected)throws Exception{JSONObject old=get(id);if(old.getLong("revision")!=expected)throw new IllegalStateException("内容已更新，请重新打开后再编辑");File dir=new File(root,id);JSONObject tomb=new JSONObject().put("id",id).put("dedupe",old.getString("dedupe")).put("capability_id",old.optString("capability_id")).put("package",old.optString("package")).put("deleted",true).put("revision",expected+1).put("user_edited",true).put("updated_at",System.currentTimeMillis());writeSync(new File(dir,"TOMBSTONE"),tomb.toString());return tomb;}
 private JSONObject read(String id,boolean includeDeleted)throws Exception{validateId(id);File dir=new File(root,id),tomb=new File(dir,"TOMBSTONE");if(tomb.isFile()){JSONObject t=new JSONObject(readText(tomb));return includeDeleted?t:null;}File pointer=new File(dir,"CURRENT");if(!pointer.isFile())return null;long rev=Long.parseLong(readText(pointer).trim());File manifest=new File(new File(new File(dir,"versions"),Long.toString(rev)),"manifest.json");return manifest.isFile()?new JSONObject(readText(manifest)):null;}
 static void validateMetadata(JSONObject metadata,JSONObject assets)throws Exception{
  if(metadata.toString().getBytes(StandardCharsets.UTF_8).length>49152)throw new IllegalArgumentException("Skill metadata exceeds budget");
  JSONArray capabilities=metadata.optJSONArray("capabilities");Set<String> ids=new HashSet<>();
  if(capabilities!=null){if(capabilities.length()>32)throw new IllegalArgumentException("Too many capability summaries");for(int i=0;i<capabilities.length();i++){JSONObject c=capabilities.getJSONObject(i);String id=c.getString("capability_id"),path=c.getString("path");if(id.isBlank()||id.length()>100||!ids.add(id)||c.getString("name").length()>160||c.getString("summary").length()>500||!assets.has(path))throw new IllegalArgumentException("Invalid capability resource summary");}}
 }
 static void validateId(String id){if(id==null||!id.matches("[A-Za-z0-9][A-Za-z0-9_.-]{0,179}")||id.contains(".."))throw new IllegalArgumentException("Invalid skill id");}
 JSONObject metadata(String id,boolean deleted)throws Exception{return read(id,deleted);}
 JSONObject bodyView(String id)throws Exception{JSONObject m=read(id,false);if(m==null||!m.optBoolean("enabled",true)||m.optString("lifecycle").equals("archived"))throw new IllegalArgumentException("Skill missing, deleted or disabled");return m.put("content_md",body(id,m.getLong("revision"))).put("view","body");}
 JSONObject resource(JSONObject p)throws Exception{
  String id=p.getString("id"),path=p.getString("path");JSONObject current=read(id,false);
  if(current==null||!current.optBoolean("enabled",true)||current.optString("lifecycle").equals("archived"))throw new IllegalStateException("Skill missing, deleted or disabled");
  long rev=p.getLong("revision");if(rev<1)throw new IllegalArgumentException("Invalid revision");
  File base=new File(new File(new File(root,id),"versions"),Long.toString(rev));
  JSONObject m=new JSONObject(readText(new File(base,"manifest.json")));JSONArray paths=m.optJSONArray("asset_paths");boolean found=path.equals("SKILL.md");
  if(paths!=null)for(int i=0;i<paths.length();i++)found|=path.equals(paths.getString(i));
  if(!found)throw new IllegalArgumentException("Resource not listed in revision");
  byte[] bytes=Files.readAllBytes(safe(base,path).toPath());int offset=p.optInt("offset",0),limit=Math.max(4,Math.min(16384,p.optInt("limit",8192)));
  if(offset<0||offset>bytes.length||(offset<bytes.length&&(bytes[offset]&0xc0)==0x80))throw new IllegalArgumentException("Invalid UTF-8 byte offset");
  int end=Math.min(bytes.length,offset+limit);while(end<bytes.length&&(bytes[end]&0xc0)==0x80)end--;
  return new JSONObject().put("id",id).put("revision",rev).put("path",path).put("offset",offset).put("total_bytes",bytes.length).put("content",new String(bytes,offset,end-offset,StandardCharsets.UTF_8)).put("next_offset",end<bytes.length?end:JSONObject.NULL).put("complete",end==bytes.length);
 }
 private String body(String id,long revision)throws Exception{String text=readText(new File(new File(new File(new File(root,id),"versions"),Long.toString(revision)),"SKILL.md"));int split=text.indexOf("\n---\n",4);return split<0?text:text.substring(split+5);}
 private JSONObject readAssets(String id,long revision)throws Exception{JSONObject out=new JSONObject();File base=new File(new File(new File(root,id),"versions"),Long.toString(revision));JSONObject m=new JSONObject(readText(new File(base,"manifest.json")));JSONArray paths=m.optJSONArray("asset_paths");if(paths!=null)for(int i=0;i<paths.length();i++){String path=paths.getString(i);File file=safe(base,path);if(file.isFile())out.put(path,readText(file));}return out;}
 private void writeAssets(File base,JSONObject assets)throws Exception{for(String path:sortedKeys(assets)){if(!(path.startsWith("scripts/")||path.startsWith("references/")||path.startsWith("assets/")))throw new IllegalArgumentException("Skill asset must be under scripts/, references/ or assets/");String value=assets.getString(path);if(value.getBytes(StandardCharsets.UTF_8).length>262144)throw new IllegalArgumentException("Skill asset exceeds 256 KiB");writeSync(safe(base,path),value);}}
 private static List<String> sortedKeys(JSONObject o){List<String> keys=new ArrayList<>();Iterator<String> it=o.keys();while(it.hasNext())keys.add(it.next());Collections.sort(keys);if(keys.size()>256)throw new IllegalArgumentException("Too many skill assets");return keys;}
 private static File safe(File base,String relative)throws Exception{if(relative.isBlank()||relative.startsWith("/")||relative.contains("\\")||relative.contains(".."))throw new IllegalArgumentException("Unsafe skill asset path");File file=new File(base,relative),canonicalBase=base.getCanonicalFile();if(!file.getCanonicalFile().toPath().startsWith(canonicalBase.toPath()))throw new IllegalArgumentException("Unsafe skill asset path");return file;}
 private String skillMarkdown(JSONObject m,String body)throws Exception{return "---\nname: "+yaml(m.getString("title"))+"\ndescription: "+yaml(m.getString("description"))+"\naios-id: "+m.getString("id")+"\naios-version: "+m.getLong("revision")+"\n---\n"+body.trim()+"\n";}
 private static String yaml(String s){return "\""+s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n")+"\"";}
 private void writePointer(File dir,long revision)throws Exception{dir.mkdirs();File next=new File(dir,"CURRENT.next");writeSync(next,Long.toString(revision)+"\n");move(next,new File(dir,"CURRENT"));File tomb=new File(dir,"TOMBSTONE");if(tomb.exists()&&!tomb.delete())throw new IOException("Cannot clear tombstone");}
 private static void writeSync(File file,String value)throws Exception{file.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(file)){out.write(value.getBytes(StandardCharsets.UTF_8));out.getFD().sync();}}
 private static String readText(File f)throws Exception{return os.aios.core.CompatFiles.readString(f.toPath(),StandardCharsets.UTF_8);}
 private static void move(File from,File to)throws Exception{try{Files.move(from.toPath(),to.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(from.toPath(),to.toPath(),StandardCopyOption.REPLACE_EXISTING);}}
 private void recover(){try{
  File[] dirs=root.listFiles(File::isDirectory);if(dirs!=null)for(File dir:dirs){if(dir.getName().startsWith(".")||new File(dir,"TOMBSTONE").exists())continue;
   File pointer=new File(dir,"CURRENT");long current=pointer.isFile()?Long.parseLong(readText(pointer).trim()):0;
   File next=new File(new File(dir,"versions"),Long.toString(current+1)),manifest=new File(next,"manifest.json");if(!manifest.isFile())continue;
   JSONObject m=new JSONObject(readText(manifest));if(!m.has("publication_id")||m.optLong("expected_revision",-1)!=current||m.getLong("revision")!=current+1||!dir.getName().equals(m.getString("id")))continue;
   if(!new File(next,"SKILL.md").isFile())throw new IOException("Incomplete published body");JSONArray assets=m.optJSONArray("asset_paths");if(assets!=null)for(int i=0;i<assets.length();i++)if(!safe(next,assets.getString(i)).isFile())throw new IOException("Incomplete published resource");
   writePointer(dir,current+1);
  }
  File[] pending=staging.listFiles();if(pending!=null)for(File f:pending)delete(f);
 }catch(Exception e){throw new IllegalStateException("Cannot recover skill publication",e);}}
 JSONObject versions(String id)throws Exception{JSONObject current=read(id,false);if(current==null)throw new IllegalArgumentException("Skill missing");JSONArray versions=new JSONArray();long latest=current.getLong("revision");for(long i=latest;i>0&&i>latest-40;i--){File manifest=new File(new File(new File(new File(root,id),"versions"),Long.toString(i)),"manifest.json");if(manifest.isFile()){JSONObject m=new JSONObject(readText(manifest));versions.put(new JSONObject().put("revision",i).put("updated_at",m.optLong("updated_at")).put("source",m.optString("source")).put("verification_kind",m.optString("verification_kind","unknown")));}}return new JSONObject().put("items",versions).put("current_revision",latest);}

 private static void delete(File f){if(!f.exists())return;if(f.isDirectory()){File[] kids=f.listFiles();if(kids!=null)for(File k:kids)delete(k);}f.delete();}
 static String hash(String value)throws Exception{byte[] b=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format(Locale.ROOT,"%02x",x));return s.toString();}
}
